mapper.select:
SELECT memories.* FROM memories
AND memories.title LIKE CONCAT('%', #{title}, '%') AND memories.source_title LIKE CONCAT('%', #{sourceTitle}, '%') AND memories.source_type LIKE CONCAT('%', #{sourceType}, '%') AND memories.original_url LIKE CONCAT('%', #{originalUrl}, '%') AND memories.original_text LIKE CONCAT('%', #{originalText}, '%') AND memories.image_path LIKE CONCAT('%', #{imagePath}, '%') AND memories.note = #{note} AND memories.created_at = #{createdAt} AND memories.updated_at = #{updatedAt}
ORDER BY memories.id DESC
